#[path = "solution.rs"]
mod solution;

use solution::{read_tagged_field, FieldError};

#[test]
fn reads_exact_content_and_empty_fields() {
    assert_eq!(
        read_tagged_field("prefix [title]  Hello\nWorld  [/title] suffix", "title"),
        Ok(Some("  Hello\nWorld  ".to_string()))
    );
    assert_eq!(read_tagged_field("[empty][/empty]", "empty"), Ok(Some(String::new())));
}

#[test]
fn supports_consecutive_fields_and_absence() {
    let input = "plain[a]one[/a][b]two[/b]tail";
    assert_eq!(read_tagged_field(input, "b"), Ok(Some("two".to_string())));
    assert_eq!(read_tagged_field(input, "c"), Ok(None));
}

#[test]
fn rejects_empty_requested_name() {
    assert_eq!(read_tagged_field("[a]x[/a]", ""), Err(FieldError::EmptyName));
}

#[test]
fn reports_duplicate_requested_fields() {
    assert_eq!(
        read_tagged_field("[a]first[/a] between [a]second[/a]", "a"),
        Err(FieldError::Duplicate)
    );
}

#[test]
fn rejects_unmatched_mismatched_and_nested_delimiters() {
    let malformed = [
        "[a]never closed",
        "orphan [/a]",
        "[a]value[/b]",
        "[a]outer[b]inner[/b][/a]",
        "[a]outer[/a][/a]",
    ];
    for input in malformed {
        assert_eq!(read_tagged_field(input, "a"), Err(FieldError::Malformed), "accepted {input:?}");
    }
}

#[test]
fn validates_text_after_an_early_match() {
    assert_eq!(
        read_tagged_field("[wanted]ok[/wanted] later [broken]", "wanted"),
        Err(FieldError::Malformed)
    );
}

#[test]
fn permits_non_delimiter_brackets_in_ordinary_text() {
    let input = "ordinary [123] and [!] brackets [x]value[/x]";
    let original = input.to_string();
    assert_eq!(read_tagged_field(input, "x"), Ok(Some("value".to_string())));
    assert_eq!(input, original);
}

